// Observation only. Z5 overlay, no profile-read hook, no mirror seed.
// Records the half-press and AF-ON ten-byte records, 0x1e71[0], and the
// AF-tab text. Not an experiment version of the profile read.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/probe_base_t6.mjs om-emu
import { writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/probe_base_t6.mjs om-emu\n');
  process.exit(2);
}
let API_SET = 0;
async function bindApi() {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  API_SET = A(0x50ac4afe);
}
const GET = 0x60063380;
const SET = 0x60063431;
const CONVERTER = 0x604050e5;
const OUT = resolve('work/out/probe-base-t6.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({ step: row.step, target: row.target, owner: row.owner, subject: row.subject, highlight: row.highlight }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};

function readKey(ctx, key, index) {
  return ctx.l.call(ctx.native(GET), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff;
}
function setKey(ctx, key, index, value) {
  const ret = ctx.l.call(ctx.native(SET), { d0: key, d1: index, a1: value }, null, null, 200000).d0 >>> 0;
  return { key, index, value, ret, back: readKey(ctx, key, index) };
}
function setPublic(ctx, sid, value) {
  const grouped = sid === 289 || sid === 66 || sid === 67;
  const argument = grouped
    ? (ctx.l.call(ctx.native(CONVERTER), { d0: sid, d1: value }, null, null, 200000).d0 >>> 0)
    : value;
  const ret = ctx.l.call(API_SET, { d0: sid, d1: argument }, null, null, 200000).d0 >>> 0;
  ctx.idle(400);
  return { sid, value, argument, ret, stored: ctx.s.get(sid) };
}
function snap(ctx, step, extra = {}) {
  const own = ctx.readOwn();
  const row = {
    step,
    target: ctx.readTarget(),
    owner: own[4],
    enabled: own[6],
    subject: readKey(ctx, 0x1e71, 0),
    k90a1: [readKey(ctx, 0x90a1, 0), readKey(ctx, 0x90a1, 1)],
    k99a1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x99a1, i)),
    k9a41: readKey(ctx, 0x9a41, 0),
    k84d1: readKey(ctx, 0x84d1, 0),
    k88b2: readKey(ctx, 0x88b2, 0),
    k5962: Array.from({ length: 6 }, (_, i) => readKey(ctx, 0x5962, i)),
    k1dd1: Array.from({ length: 10 }, (_, i) => readKey(ctx, 0x1dd1, i)),
    k1df1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x1df1, i)),
    k1e01: readKey(ctx, 0x1e01, 0),
    kdfa1: readKey(ctx, 0xdfa1, 0),
    k99d2: [readKey(ctx, 0x99d2, 0), readKey(ctx, 0x99d2, 1), readKey(ctx, 0x99d2, 2)],
    k1db1: readKey(ctx, 0x1db1, 0),
    k1dc1: readKey(ctx, 0x1dc1, 0),
    zone: ctx.readByte(0xa031e920),
    mirror0: ctx.readByte(0xa031eeb0),
    ...extra,
  };
  emit(row);
  return row;
}

const result = await runZone({
  checkout,
  outPath: 'work/out/session-probe-base-t6.jsonl',
  tag: 'probe-base-t6',
  candidate: true,
  help: true,
  rowLabel: true,
  overlayCsv: 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes-c1.csv',
  fatalShots: true,
  explanation: 'Observation of Z5. No profile-read hook. No mirror seed. Role: observe.',
  change: 'none',
  async drive(ctx) {
    await bindApi();
    const counts = { home: 0, writer: 0 };
    ctx.l.observe(ctx.native(0x60a8f6bb), () => { counts.home += 1; }, 'obs-home-builder');
    ctx.l.observe(ctx.native(0x609b3c79), () => { counts.writer += 1; }, 'obs-half-writer');
    ctx.bringUp();
    ctx.s.switch_input('lever', 1);
    ctx.s.camapp.pump();
    ctx.idle(400);
    const mode = setPublic(ctx, 289, 0);
    emit({ step: 'mode', mode, subject: readKey(ctx, 0x1e71, 0), focus: ctx.s.get(289), active: ctx.s.get(25) });
    snap(ctx, 'after-saf', { counts: { ...counts } });
    ctx.key('s1', 'down');
    ctx.idle(300);
    const s1 = ctx.shot('s1');
    snap(ctx, 's1-down', { counts: { ...counts }, highlight: s1.highlight, texts: s1.texts });
    ctx.key('s1', 'up');
    ctx.idle(200);
    ctx.key('afon', 'down');
    ctx.idle(300);
    const af = ctx.shot('afon');
    snap(ctx, 'afon-down', { counts: { ...counts }, highlight: af.highlight, texts: af.texts });
    ctx.key('afon', 'up');
    ctx.idle(200);
    const all = setKey(ctx, 0x84d1, 0, 2);
    const d0 = setKey(ctx, 0x1dd1, 0, 1);
    const d1 = setKey(ctx, 0x1dd1, 1, 1);
    const area = setKey(ctx, 0x99a1, 0, 0);
    emit({ step: 'poke-all', all, d0, d1, area });
    ctx.key('s1', 'down');
    ctx.idle(300);
    snap(ctx, 's1-after-poke', { counts: { ...counts } });
    ctx.key('s1', 'up');
    ctx.idle(200);
    ctx.press('menu');
    for (let i = 0; i < 20; i++) ctx.press('left');
    const menu = ctx.shot('af-tab');
    emit({
      step: 'af-tab',
      highlight: menu.highlight,
      texts: menu.texts,
      subject: readKey(ctx, 0x1e71, 0),
      screen: ctx.s.screen(),
    });
    emit({ step: 'done', ok: true, counts });
  },
});
emit({ step: 'session', ok: result.ok, failed: result.failed });
if (!result.ok) process.exit(1);
